{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useState, type FormEvent } from "react";
import { toast } from "sonner";
import { formatPrice } from "@/data/catalog";
import { COMPANY } from "@/data/company";
import { cartSubtotal, resolveLines, useStore } from "@/lib/store";

export const Route = createFileRoute("/checkout")({
  head: () => ({
    meta: [
      { title: "Checkout | Pickrel Brothers Wholesale Supply, Dayton OH" },
      {
        name: "description",
        content:
          "Complete your Pickrel Brothers order: choose will-call pickup or jobsite delivery, enter a PO number and submit to your account for processing.",
      },
      { property: "og:title", content: "Checkout | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Will-call pickup or jobsite delivery, PO number and account terms.",
      },
    ],
  }),
  component: CheckoutPage,
});

function CheckoutPage() {
  const { cart, poNumber, setPoNumber, placeOrder } = useStore();
  const lines = resolveLines(cart);
  const subtotal = cartSubtotal(lines);
  const [fulfillment, setFulfillment] = useState<"willcall" | "delivery">("willcall");
  const [orderId, setOrderId] = useState<string | null>(null);

  function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const id = placeOrder(poNumber || "N/A");
    setOrderId(id);
    toast.success(`Order ${id} submitted`);
  }

  if (orderId) {
    return (
      <div className="container-page py-16">
        <div className="mx-auto max-w-xl rounded-md border border-border bg-card p-10 text-center shadow-card">
          <h1 className="font-display text-3xl font-bold uppercase text-navy">Order submitted</h1>
          <p className="mt-3 text-sm text-muted-foreground">
            Confirmation <span className="font-mono font-semibold text-foreground">{orderId}</span>. A
            Pickrel Brothers representative will confirm pricing, availability and freight. Questions?
            Call {COMPANY.phone}.
          </p>
          <div className="mt-6 flex flex-wrap justify-center gap-3">
            <Link
              to="/account"
              className="rounded-md bg-navy px-5 py-2.5 text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
            >
              View order history
            </Link>
            <Link
              to="/products"
              search={{ q: "", category: "", brand: "" }}
              className="rounded-md border border-input px-5 py-2.5 text-sm font-semibold text-navy hover:bg-secondary"
            >
              Keep shopping
            </Link>
          </div>
        </div>
      </div>
    );
  }

  if (lines.length === 0) {
    return (
      <div className="container-page py-16 text-center">
        <h1 className="font-display text-3xl font-bold uppercase text-navy">Checkout</h1>
        <p className="mt-3 text-muted-foreground">There's nothing in your cart yet.</p>
        <Link
          to="/products"
          search={{ q: "", category: "", brand: "" }}
          className="mt-6 inline-block rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
        >
          Browse the catalog
        </Link>
      </div>
    );
  }

  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Checkout</h1>

      <form onSubmit={onSubmit} className="mt-8 grid gap-8 lg:grid-cols-[1fr_340px]">
        <div className="space-y-6">
          <section className="rounded-md border border-border bg-card p-6 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Contact & account</h2>
            <div className="mt-4 grid gap-4 sm:grid-cols-2">
              <Field label="Name" name="name" required />
              <Field label="Company" name="company" required />
              <Field label="Email" name="email" type="email" required />
              <Field label="Phone" name="phone" type="tel" required />
              <label className="text-sm font-semibold text-navy">
                PO number
                <input
                  value={poNumber}
                  onChange={(e) => setPoNumber(e.target.value)}
                  className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
                />
              </label>
              <Field label="Account number (if known)" name="account" />
            </div>
          </section>

          <section className="rounded-md border border-border bg-card p-6 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Fulfillment</h2>
            <div className="mt-4 grid gap-3 sm:grid-cols-2">
              <FulfillmentOption
                active={fulfillment === "willcall"}
                onSelect={() => setFulfillment("willcall")}
                title="Will-call pickup"
                body={`${COMPANY.address1}, ${COMPANY.address2}. ${COMPANY.hours}.`}
              />
              <FulfillmentOption
                active={fulfillment === "delivery"}
                onSelect={() => setFulfillment("delivery")}
                title="Jobsite delivery"
                body="Local delivery throughout the Dayton, Cincinnati and Springfield areas."
              />
            </div>
            {fulfillment === "delivery" && (
              <div className="mt-4 grid gap-4 sm:grid-cols-2">
                <Field label="Delivery address" name="address" required />
                <Field label="City" name="city" required />
                <Field label="State" name="state" required />
                <Field label="ZIP" name="zip" required />
                <label className="sm:col-span-2 text-sm font-semibold text-navy">
                  Delivery instructions
                  <textarea
                    name="instructions"
                    rows={3}
                    className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
                  />
                </label>
              </div>
            )}
          </section>

          <section className="rounded-md border border-border bg-card p-6 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Payment</h2>
            <p className="mt-2 text-sm text-muted-foreground">
              Orders are billed to your Pickrel Brothers account on standard terms. If you don't have an
              account yet, we'll contact you to set one up before the order ships.
            </p>
            <label className="mt-4 flex items-start gap-3 text-sm text-muted-foreground">
              <input type="checkbox" required className="mt-1 h-4 w-4" />
              <span>
                I authorize this order and agree to Pickrel Brothers'{" "}
                <Link to="/policies" className="font-semibold text-sky hover:underline">
                  terms and policies
                </Link>
                .
              </span>
            </label>
          </section>
        </div>

        <aside className="h-fit rounded-md border border-border bg-card p-6 shadow-card">
          <h2 className="font-display text-lg font-bold uppercase text-navy">Order summary</h2>
          <ul className="mt-4 space-y-3 text-sm">
            {lines.map((l) => (
              <li key={l.slug} className="flex justify-between gap-3">
                <span className="text-muted-foreground">
                  {l.qty} × {l.product.name}
                </span>
                <span className="font-semibold text-foreground">
                  {l.extended === null ? "Call" : formatPrice(l.extended)}
                </span>
              </li>
            ))}
          </ul>
          <div className="mt-4 flex justify-between border-t border-border pt-4 text-sm">
            <span className="font-semibold text-navy">Subtotal</span>
            <span className="font-bold text-foreground">{formatPrice(subtotal)}</span>
          </div>
          <p className="mt-1 text-xs text-muted-foreground">
            Freight and tax confirmed by your sales representative.
          </p>
          <button
            type="submit"
            className="mt-5 w-full rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
          >
            Submit order
          </button>
        </aside>
      </form>
    </div>
  );
}

function FulfillmentOption({
  active,
  onSelect,
  title,
  body,
}: {
  active: boolean;
  onSelect: () => void;
  title: string;
  body: string;
}) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={`rounded-md border-2 p-4 text-left transition-colors ${
        active ? "border-sky bg-sky-soft" : "border-border hover:border-sky"
      }`}
    >
      <span className="block font-display font-bold uppercase text-navy">{title}</span>
      <span className="mt-1 block text-xs text-muted-foreground">{body}</span>
    </button>
  );
}

function Field({
  label,
  name,
  type = "text",
  required = false,
}: {
  label: string;
  name: string;
  type?: string;
  required?: boolean;
}) {
  return (
    <label className="text-sm font-semibold text-navy">
      {label}
      {required && <span className="text-destructive"> *</span>}
      <input
        name={name}
        type={type}
        required={required}
        className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
      />
    </label>
  );
}
